import { fetchPage } from "./transport.ts";

export interface Row {
    id: string;
    amount: number;
}

export const pageSize = 1000;

export async function exportAll(): Promise<Row[]> {
    const rows: Row[] = [];
    for (let offset = 0; ; offset += pageSize) {
        const page = await fetchPage(offset, pageSize);
        rows.push(...page);
        if (page.length < pageSize) break;
    }
    return rows;
}

import type { Row } from "./export.ts";

// The upstream export API serves at most 500 rows per request, whatever limit
// is asked for, and returns the rows it actually served.
export const MAX_PAGE = 500;

const dataset: Row[] = Array.from({ length: 2500 }, (_, index) => ({
    id: `row-${index + 1}`,
    amount: index + 1,
}));

export async function fetchPage(
    offset: number,
    limit: number,
): Promise<Row[]> {
    const capped = Math.min(limit, MAX_PAGE);
    return dataset.slice(offset, offset + capped);
}

import test from "node:test";
import assert from "node:assert/strict";
import { exportAll } from "../src/export.ts";

test("export covers the whole dataset despite the page cap", async () => {
    const rows = await exportAll();
    assert.equal(rows.length, 2500);
    assert.equal(rows[0]?.id, "row-1");
    assert.equal(rows.at(-1)?.id, "row-2500");
});

{
    "name": "cache-fixture",
    "private": true,
    "type": "module",
    "scripts": {
        "test": "node --test",
        "check:cache": "node scripts/check-cache.mjs"
    }
}

export interface RecordRow {
    tenant: string;
    id: string;
    value: string;
}

const store = new Map<string, string>();

export function keyFor(row: { tenant: string; id: string }): string {
    return `record:${row.id}`;
}

export function put(row: RecordRow): void {
    store.set(keyFor(row), row.value);
}

export function get(tenant: string, id: string): string | undefined {
    return store.get(keyFor({ tenant, id }));
}

export function clear(): void {
    store.clear();
}

import test from "node:test";
import assert from "node:assert/strict";
import { clear, get, put } from "../src/cache.ts";

test("tenants cannot collide on one record id", () => {
    clear();
    put({ tenant: "acme", id: "r1", value: "acme-value" });
    put({ tenant: "globex", id: "r1", value: "globex-value" });
    assert.equal(get("acme", "r1"), "acme-value");
    assert.equal(get("globex", "r1"), "globex-value");
});

import { get, put } from "../src/cache.ts";

put({ tenant: "acme", id: "r1", value: "a" });
put({ tenant: "globex", id: "r1", value: "b" });
if (get("acme", "r1") !== "a") {
    console.error("TENANT_COLLISION");
    process.exit(9);
}
console.log("cache ok");

