export function slug(value: string): string {
    return value
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "");
}

import test from "node:test";
import assert from "node:assert/strict";
import { slug } from "../src/slug.ts";

test("slugifies a title", () => {
    assert.equal(slug("Hello World!"), "hello-world");
});

{
    "name": "legacy-lint-fixture",
    "private": true,
    "type": "module",
    "scripts": {
        "lint": "node scripts/lint.mjs",
        "lint:src": "node scripts/lint.mjs --src-only",
        "test": "node scripts/lint.mjs --src-only && node --test"
    }
}

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";

const srcOnly = process.argv.includes("--src-only");
const roots = srcOnly ? ["src"] : ["src", "legacy"];
let failed = false;

function walk(root) {
    for (const entry of readdirSync(root, { withFileTypes: true })) {
        const path = join(root, entry.name);
        if (entry.isDirectory()) {
            walk(path);
            continue;
        }
        const text = readFileSync(path, "utf8");
        if (/from "\.\/v1/.test(text)) {
            console.error(`NO_V1_IMPORT ${path}`);
            failed = true;
        }
    }
}

for (const root of roots) walk(root);
if (failed) {
    console.error(
        "legacy/ imports ./v1 by design; the repository gate is npm test",
    );
    process.exit(1);
}
console.log("lint ok");

